python3 -c "
import urllib.request, json

# Search for biocontainers with scikit-learn
for query in ['scikit-learn', 'scikit_learn', 'sklearn', 'numpy-scipy-scikit-learn', 'pandas']:
    url = f'https://quay.io/api/v1/find/repositories?query=biocontainers/{query}&limit=4'
    try:
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read())
            repos = data.get('results', data.get('repositories', []))
            if repos:
                print(f'--- {query} ---')
                for r in repos[:4]:
                    print(f\"  {r.get('namespace')}/{r.get('name')}: {r.get('description', '')[:120]}\")
            else:
                print(f'{query}: no results')
    except Exception as e:
        print(f'{query}: error - {e}')
"

